{
  "segment_function": "Discussing the artificial adaptations of 'carapace' and 'prosthesis' as personal protective equipment and apparatuses that mediate human sensation, perception, and interaction under hazardous environmental conditions.",
  "claims": [
    {
      "claim": "The concept of 'carapace' is not limited to literal armoring or hard structures, but can include soft personal protective equipment such as surgical masks, respirators, cooling garments, encapsulated hazmat gear, and heat-resistant face shields.",
      "claim_type": "author_position",
      "supporting_excerpt": "But it is not literal: examples of what I am calling “carapace” can perfectly well be soft, like the surgical masks and respirators that were already used in cities with high levels of particulate air pollution, became ubiquitous in many places during the pandemic, and are now being repurposed across North America as protection from hazardous levels of near-surface wild ﬁre smoke. Other examples might include everything from the cooling garments increasingly worn by military personnel and ﬁrst responders working in extreme conditions, to encapsulated hazmat gear, to the heat-resistant face shields used by welders and furnace operators.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "The 'prosthesis' adaptation refers to apparatuses that facilitate sensation, perception, action, or interaction at a distance from the body, ranging from teleconferencing software and automation to simpler devices.",
      "claim_type": "author_position",
      "supporting_excerpt": "A second type of adaptation might be called the “prosthesis,” though what I have in mind are apparatuses that facilitate sensation and perception, and possibly also action or interaction, at a distance from the body.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "carapace",
      "definition": "Personal protective equipment—which can be either hard or soft, such as masks, respirators, cooling garments, hazmat gear, and face shields—used to protect the body from hazardous environmental conditions."
    },
    {
      "term": "prosthesis",
      "definition": "Apparatuses that facilitate sensation, perception, action, or interaction at a distance from the body, including teleconferencing software, automation, robotics, remote sensing, and simpler devices."
    }
  ],
  "distinctions": [
    {
      "item_a": "carapace",
      "item_b": "prosthesis",
      "distinction": "Carapace functions as personal protective equipment worn on or enclosing the body against immediate hazards, whereas a prosthesis functions as an apparatus that facilitates sensation, perception, action, or interaction at a distance from the body."
    }
  ]
}

